/** The source of the generated modules. Values are JSON, so they read back exactly. */
import { ICONS, headTags } from '@xcwds/core';
import type { ClientData, WorkerData } from '../data.js';
import type { BuildState } from './state.js';

const json = (value: unknown) => JSON.stringify(value);

export const HEADER =
	'// Generated by @xcwds/sveltekit from the xcwds config whenever svelte.config.js loads. Do not edit.\n';

/** Files the build emits beside SvelteKit's output, relative to the base path. */
export function emittedFiles(state: BuildState): string[] {
	return ['manifest.webmanifest', ...(state.config.brand.icon ? Object.values(ICONS) : [])];
}

/** `import pN from '<plugin>/<entry>'` for each plugin with that entry, and the pairs list. */
function imports(state: BuildState, entry: 'client' | 'worker') {
	const list = state.plugins.filter((p) => p[entry]);
	return {
		lines: list.map((p, i) => `import p${i} from ${json(`${p.name}/${entry}`)};\n`).join(''),
		pairs: `[${list.map((p, i) => `[p${i}, ${json(p.options)}]`).join(', ')}]`
	};
}

/** `virtual:xcwds/client`, for the page bundle (client and prerender). */
export function clientModule(state: BuildState): string {
	const data: ClientData = {
		name: state.config.brand.name,
		base: state.base,
		storagePrefix: state.config.storage.prefix,
		routes: state.routes,
		head: state.head,
		tags: headTags(state.config, { base: state.base })
	};
	const { lines, pairs } = imports(state, 'client');
	return `${lines}export const plugins = ${pairs};\nexport const data = ${json(data)};\n`;
}

/** `.xcwds/worker.js`, imported by `src/service-worker.ts`. */
export function workerModule(state: BuildState): string {
	const data: WorkerData = {
		name: state.config.brand.name,
		storagePrefix: state.config.storage.prefix,
		routes: state.routes,
		assets: emittedFiles(state)
	};
	const { lines, pairs } = imports(state, 'worker');
	const extra = state.worker.map((m) => `import ${json(m)};\n`).join('');
	return (
		HEADER +
		"import { base, build, files, prerendered, version } from '$service-worker';\n" +
		"import { startWorker } from '@xcwds/sveltekit/worker';\n" +
		lines +
		extra +
		`startWorker({ base, build, files, prerendered, version, plugins: ${pairs}, ...${json(data)} });\n`
	);
}

/** `.xcwds/build.js`: every plugin's `.` entry, imported from the app's root like the config. */
export function buildModule(names: string[]): string {
	const lines = names.map((name, i) => `import * as p${i} from ${json(name)};\n`).join('');
	return `${HEADER}${lines}export default [${names.map((_, i) => `p${i}`).join(', ')}];\n`;
}
